    } else if (status === 'approved_pending_listing') {
      items.push({ label: '涓婃灦', action: 'list' });
    } else if (status === 'listed') {
      items.push({ label: '鍋滅敤', action: 'disable' });
      items.push({ label: '涓嬫灦', action: 'offline', danger: true });
    } else if (status === 'disabled') {
      items.push({ label: '鍚敤', action: 'enable' });
      items.push({ label: '涓嬫灦', action: 'offline', danger: true });
    }
    return items;
